[ "$rc" = 2 ] || { echo "10pm end: expected exit 2, got $rc"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a booking with a bad end time was stored"; fail=1; }
rm -f "$t"; exit $fail

